showLoading('카드를 불러오는 중입니다');
try {
  await loadCards();
} finally {
  hideLoading();
}

function renderNextChunk(start, size = 50) {
  const end = Math.min(start + size, cards.length);
  render(cards.slice(start, end));
  if (end < cards.length) {
    requestAnimationFrame(() => renderNextChunk(end, size));
  }
}
renderNextChunk(0);
